`void Order::markPaid(const std::string& reference) {
    if (status != OrderStatus::Created) {
        throw std::logic_error("Only new orders can be paid");
    }
    if (reference.empty()) throw std::invalid_argument("reference required");
    paymentReference = reference;
    status = OrderStatus::Paid;
}` This operation checks the current state and required input before changing the order.

